[##ringmaker.clearNonEquippedInventory(false)]
[##
    var itemClass = ITEM_innoxia_pills_broodmother.getClass().getClassLoader().loadClass('com.lilithsthrone.game.inventory.item.ItemType');
    var itemMethod = itemClass.getMethod('getAllItems');
    function itemFilter(item) {
        var itemId = item.getId();
        if(itemId.contains('xys_') && !item.getItemTags().contains(ITEM_TAG_REMOVE_FROM_DEBUG_SPAWNER))
            if(itemId.contains('xys_rings_ring_special_')) {
                ringmaker.addItem(itemGen.generateItem(itemId), 1, false, false);
            }
            else {
                ringmaker.addItem(itemGen.generateItem(itemId), 5, false, false);
            };
        };
    itemMethod.invoke(null).forEach(itemFilter); 
]
[##
    var clothingClass = CLOTHING_innoxia_torso_blouse.getClass().getClassLoader().loadClass('com.lilithsthrone.game.inventory.clothing.ClothingType');
    var clothingMethod = clothingClass.getMethod('getAllClothing');
    function clothingFilter(clothing) {
        var clothingId = clothing.getId();
        if(clothingId.contains('xys_') && !clothingId.equals('xys_rings_ring_portal') && !clothingId.contains('xys_magical_girl_')) {
            ringmaker.addClothing(itemGen.generateClothing(clothingId, false), 1, false, false);
        };
    };
    clothingMethod.invoke(null).forEach(clothingFilter); 
    ringmaker.addClothing(itemGen.generateClothing('xys_magical_girl_unknown_bracelet', COLOUR_FEMININE, COLOUR_CLOTHING_STEEL, null, false), false);
    ringmaker.addClothing(itemGen.generateClothing('xys_magical_girl_unknown_bracelet_fb', COLOUR_ANDROGYNOUS, COLOUR_CLOTHING_STEEL, null, false), false)
]
[##
    var weaponClass = WEAPON_innoxia_crystal_rare.getClass().getClassLoader().loadClass('com.lilithsthrone.game.inventory.weapon.WeaponType');
    var weaponMethod = weaponClass.getMethod('getAllWeapons');
    function weaponFilter(weapon) {
        var weaponId = weapon.getId();
        if(weaponId.contains('xys_') && !weaponId.contains('xys_ringmaker') && !weapon.getItemTags().contains(ITEM_TAG_REMOVE_FROM_DEBUG_SPAWNER)) {
            ringmaker.addWeapon(itemGen.generateWeapon(weaponId), RND.nextInt(2)+1, false, false);
        };
    };
    weaponMethod.invoke(null).forEach(weaponFilter); 
]
[##ringmaker.setItemTagsToBuy(Array(ITEM_TAG_SOLD_BY_NYAN, ITEM_TAG_SOLD_BY_KATE, ITEM_TAG_SOLD_BY_FINCH))]

scene.preParsingEffects:
[#
    ringmaker.unequipClothingIntoVoid(IS_TORSO_OVER, false, ringmaker);
    ringmaker.setAgeAppearanceDifference(-5);
    ringmaker.setDescription("[ringmaker.Name] is the demonic rabbit-morph ringmaker and shopkeeper of a nameless jewellery store in Shopping Arcade. She usually dresses up as an old crone to blend in with the crowd, though she deems you trustworthy enough to drop the facade. She's pretty vain, and is a massive slut.");
    ringmaker.setPlayerKnowsName(true);
    ringmaker.setRaceConcealed(false);
    ringmaker.setCombatBehaviour(COMBAT_BEHAVIOUR_BALANCED);
    ringmaker.equipMainWeaponFromNowhere(itemGen.generateWeapon('xys_ringmaker_GOODBYE'));
    ringmaker.equipOffhandWeaponFromNowhere(itemGen.generateWeapon('xys_ringmaker_KISS'));
    ringmaker.equipMove('xys_mag_dump_kiss'); ringmaker.equipMove('xys_mag_dump_goodbye');
]
